static int connect4(const char*address,unsigned short port,SOCKET*out){SOCKET s;struct sockaddr_in a;memset(&a,0,sizeof(a));a.sin_family=AF_INET;a.sin_port=htons(port);a.sin_addr.s_addr=inet_addr(address);s=socket(AF_INET,SOCK_STREAM,IPPROTO_TCP);if(s==INVALID_SOCKET)return 0;if(connect(s,(struct sockaddr*)&a,sizeof(a))==SOCKET_ERROR){closesocket(s);return 0;}*out=s;return 1;}
static int wait_one(pst_connection*c){PST_WAIT_RESULT w;memset(&w,0,sizeof(w));return pst_connection_wait(c,2000,&w)==PST_RESULT_OK&&!w.timed_out&&w.ready_interest;}
static pst_runtime *runtime_new(counts*n){PST_RUNTIME_OPTIONS o;pst_runtime*r=NULL;memset(&o,0,sizeof(o));o.struct_size=sizeof(o);o.api_version=PST_API_VERSION;o.selection=PST_BACKEND_SELECTION_EXACT;o.exact_backend_id="openssl";if(pst_runtime_create(&o,&r)==PST_RESULT_OK)n->runtimes_created++;return r;}
static void runtime_drop(pst_runtime*r,counts*n){if(r){pst_runtime_release(r);n->runtimes_destroyed++;}}
